  const notice = id => (D.notice_calendar || []).filter(r => r.measure === id && r.status === 'soon').map(r => r.notice_by).sort()[0];
  const X = D.shifting, shape = X.hourly_shape, g = X.grid_mid.Zurich * 1000;
