    s += `<text x="${L - 10}" y="${y + 4}" text-anchor="end" style="fill:var(--ink)">${esc(r.model)}${/life cycle/.test(r.co2.label) ? ' (life cycle)' : ''}</text>`;
    if (r.co2.high > r.co2.low) s += `<line x1="${X(r.co2.low)}" x2="${X(r.co2.high)}" y1="${y}" y2="${y}" stroke="${c}" stroke-width="6" stroke-linecap="round" opacity=".45"/>`;
