      <div class="kpis" style="grid-template-columns:repeat(2,1fr);box-shadow:none"><div class="kpi"><div class="k">Energy</div><div class="v">${(e.kwh || 0).toFixed(2)} kWh</div><div class="r">${(e.gpu_hours || 0).toFixed(2)} GPU-hours</div></div>
        <div class="kpi"><div class="k">CO₂</div><div class="v">${((e.co2_kg || 0) * 1000).toFixed(0)} g</div><div class="r">Swiss consumption mix</div></div></div>
